837	// One real turn through the handler: the model asks for `call` and, handed its result, answers.
838	async function turnOver(call: ToolCall, registry: ToolRegistry): Promise<string[]> {
839	  let requests = 0;
840	  const provider: AIProvider = {
841	    async *sendMessage(): AsyncGenerator<MessageChunk> {
842	      requests++;
843	      const asks: MessageChunk[] = [
844	        {type: 'tool_use', toolCall: call},
845	        {type: 'stop', stopReason: 'tool_use'},
846	      ];
847	      yield* requests === 1 ? asks : [text('all done'), STOP];
848	    },
849	    async generateStructured<T>(): Promise<T> {
850	      return {} as T;
851	    },
852	  };
853	  const sent: OutgoingMessage[] = [];
854	  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
855	  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Failure test.'}), registry);
856	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
857	
858	  await createMessageHandler(orchestrator)(ws, session, userMessage('hello'));
859	  return wire(sent);
860	}
