862	// What the client saw of the turn: whether the answer streamed, the last frame, and any error frames.
863	function outcomeOf(frames: string[]): {answered: boolean; last: string | undefined; errors: string[]} {
864	  return {
865	    answered: frames.some(frame => frame.startsWith('delta') && frame.endsWith(JSON.stringify('all done'))),
866	    last: frames.at(-1),
867	    errors: frames.filter(frame => frame.startsWith('error')),
868	  };
869	}
