    const listForMock = jest.fn(async () => [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ]);
    const orchestrator = {
      processMessageStream: async function* () {},
    } as unknown as ChatOrchestrator;
    const store = {listFor: listForMock} as unknown as SessionStore;
